mapper.select:
SELECT source_id AS sourceId, source_key AS sourceKey, source_type AS sourceType, agency_code AS agencyCode, agency_name AS agencyName, source_url AS sourceUrl, enabled, DATE_FORMAT(last_checked_at, '%Y-%m-%d %H:%i:%s') AS lastCheckedAt, DATE_FORMAT(last_success_at, '%Y-%m-%d %H:%i:%s') AS lastSuccessAt, last_error_message AS lastErrorMessage FROM rag_collection_sources WHERE enabled = 'Y'
AND agency_code = #{agencyCode}
ORDER BY agency_code, source_key

mapper.update:
UPDATE rag_collection_sources
SET last_checked_at = NOW(),
    last_success_at = CASE WHEN #{success} THEN NOW() ELSE last_success_at END,
    last_error_message = #{errorMessage}
WHERE source_id = #{sourceId}

mapper.select:
SELECT article_id
FROM rag_source_articles
WHERE source_id = #{sourceId}
  AND external_id = #{externalId}
LIMIT 1
